16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "address_line1")
43	    private String addressLine1;
44	
45	    @Column(name = "address_line2")
46	    private String addressLine2;
47	
48	    @Column(name = "city")
49	    @NotEmpty
50	    private String city;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    private String email;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @Column(name = "household_size")
79	    private Integer householdSize;
80	
81	    @Column(name = "postcode")
82	    private String postcode;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @Transient
91	    private boolean declaredHouseholdMember;
92	
93	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
94	    private Set<Pet> pets;
95	
96	    public String getAddress() {
97	        return this.address;
98	    }
99	
100	    public void setAddress(String address) {
101	        this.address = address;
102	    }
103	
104	    public String getAddressLine1() {
105	        return this.addressLine1;
106	    }
107	
108	    public void setAddressLine1(String addressLine1) {
109	        this.addressLine1 = addressLine1;
110	    }
111	
112	    public String getAddressLine2() {
113	        return this.addressLine2;
114	    }
115	
116	    public void setAddressLine2(String addressLine2) {
117	        this.addressLine2 = addressLine2;
118	    }
119	
120	    public String getCity() {
121	        return this.city;
122	    }
123	
124	    public void setCity(String city) {
125	        this.city = city;
126	    }
127	
128	    public String getTelephone() {
129	        return this.telephone;
130	    }
131	
132	    public void setTelephone(String telephone) {
133	        this.telephone = telephone;
134	    }
135	
136	    public String getEmail() {
137	        return this.email;
138	    }
139	
140	    public void setEmail(String email) {
141	        this.email = email;
142	    }
143	
144	    public LocalDate getRegistrationDate() {
145	        return this.registrationDate;
146	    }
147	
148	    public void setRegistrationDate(LocalDate registrationDate) {
149	        this.registrationDate = registrationDate;
150	    }
151	
152	    public LocalDate getBirthDate() {
153	        return this.birthDate;
154	    }
155	
156	    public void setBirthDate(LocalDate birthDate) {
157	        this.birthDate = birthDate;
158	    }
159	
160	    public String getCustomerCode() {
161	        return this.customerCode;
162	    }
163	
164	    public void setCustomerCode(String customerCode) {
165	        this.customerCode = customerCode;
166	    }
167	
168	    public String getHouseholdId() {
169	        return this.householdId;
170	    }
171	
172	    public void setHouseholdId(String householdId) {
173	        this.householdId = householdId;
174	    }
175	
176	    public Integer getNamesakeCount() {
177	        return this.namesakeCount;
178	    }
179	
180	    public void setNamesakeCount(Integer namesakeCount) {
181	        this.namesakeCount = namesakeCount;
182	    }
183	
184	    public Boolean getBulkSignupWarning() {
185	        return this.bulkSignupWarning;
186	    }
187	
188	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
189	        this.bulkSignupWarning = bulkSignupWarning;
190	    }
191	
192	    public Integer getHouseholdSize() {
193	        return this.householdSize;
194	    }
195	
196	    public void setHouseholdSize(Integer householdSize) {
197	        this.householdSize = householdSize;
198	    }
199	
200	    public String getPostcode() {
201	        return this.postcode;
202	    }
203	
204	    public void setPostcode(String postcode) {
205	        this.postcode = postcode;
206	    }
207	
208	    /**
209	     * Whether this owner deliberately declared, when created, that it shares its
210	     * household with an existing owner (the request's {@code sharesHousehold} flag).
211	     * A declared member is created despite occupying an existing household and is not
212	     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
213	     */
214	    @Transient
215	    public boolean isDeclaredHouseholdMember() {
216	        return this.declaredHouseholdMember;
217	    }
218	
219	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
220	        this.declaredHouseholdMember = declaredHouseholdMember;
221	    }
222	
223	    /**
224	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
225	     * existing owner: not a hard duplicate, but sharing that owner's last name and postcode
226	     * while carrying a different telephone. See {@link #getPossibleDuplicateOf()}.
227	     */
228	    public Boolean getPossibleDuplicate() {
229	        return this.possibleDuplicate;
230	    }
231	
232	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
233	        this.possibleDuplicate = possibleDuplicate;
234	    }
235	
236	    /**
237	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
238	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
239	     */
240	    public Integer getPossibleDuplicateOf() {
241	        return this.possibleDuplicateOf;
242	    }
243	
244	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
245	        this.possibleDuplicateOf = possibleDuplicateOf;
246	    }
247	
248	    /**
249	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
250	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
251	     * Derived from the owner's own fields, so it stays consistent with them.
252	     */
253	    @Transient
254	    public String getMembershipNumber() {
255	        if (this.customerCode == null || this.registrationDate == null) {
256	            return null;
257	        }
258	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
259	    }
260	
261	    /**
262	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
263	     * over the digits of the customer code. Derived from the owner's own customer code,
264	     * so it stays consistent with it.
265	     */
266	    @Transient
267	    public Integer getCheckDigit() {
268	        if (this.customerCode == null) {
269	            return null;
270	        }
271	        return LuhnCheckDigit.of(this.customerCode);
272	    }
273	
274	    /**
275	     * The owner's membership points, starting at zero: two points are added when an email is
276	     * on file, one more when the owner is unique (namesake count of zero), two more for a
277	     * household of three or more, and three more when the owner has accrued more than a year of
278	     * tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays consistent
279	     * with them.
280	     */
281	    @Transient
282	    public Integer getMembershipPoints() {
283	        int points = 0;
284	        boolean hasEmail = this.email != null && !this.email.isEmpty();
285	        if (hasEmail) {
286	            points += 2;
287	        }
288	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
289	        if (unique) {
290	            points += 1;
291	        }
292	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
293	        if (largeHousehold) {
294	            points += 2;
295	        }
296	        boolean tenured = this.registrationDate != null
297	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
298	        if (tenured) {
299	            points += 3;
300	        }
301	        return points;
302	    }
303	
304	    /**
305	     * The owner's membership level, a number from 1 to 4, derived from their
306	     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}). Derived
307	     * from the owner's own fields, so it stays consistent with them.
308	     */
309	    @Transient
310	    public Integer getMembershipLevel() {
311	        return MembershipLevel.forPoints(getMembershipPoints());
312	    }
313	
314	    /**
315	     * The owner's locality: the canonical region, taken as the region segment of the
316	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
317	     * consistent with the owner's identity. When no customer code has been assigned yet
318	     * it falls back to resolving the region directly from the postcode and city (see
319	     * {@link RegionResolver}), the same rule the customer code itself is built from.
320	     */
321	    @Transient
322	    public String getLocality() {
323	        if (this.customerCode != null) {
324	            int separator = this.customerCode.indexOf('-');
325	            if (separator > 0) {
326	                return this.customerCode.substring(0, separator);
327	            }
328	        }
329	        return RegionResolver.regionFor(this.postcode, this.city);
330	    }
331	
332	    /**
333	     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
334	     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
335	     * stays consistent with the owner's region. Null when the locality has no known timezone.
336	     */
337	    @Transient
338	    public String getTimezone() {
339	        return RegionTimezoneTable.timezoneFor(getLocality());
340	    }
341	
342	    /**
343	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
344	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
345	     * stays consistent with them.
346	     */
347	    @Transient
348	    public String getContactPreference() {
349	        boolean hasEmail = this.email != null && !this.email.isEmpty();
350	        return hasEmail ? "EMAIL" : "PHONE";
351	    }
352	
353	    /**
354	     * The owner's telephone formatted for human display: the stored E.164 number
355	     * rendered as its country calling code, a space and the national digits grouped
356	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
357	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
358	     * consistent with it. See {@link TelephoneFormatter}.
359	     */
360	    @Transient
361	    public String getTelephoneDisplay() {
362	        return TelephoneFormatter.toDisplay(this.telephone);
363	    }
364	
365	    /**
366	     * The owner's identity key: the single derived value used to detect duplicate owners,
367	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
368	     * Two owners are duplicates only when their whole identity keys are equal, so members
369	     * of one household (sharing a household id) but with different telephones stay distinct.
370	     * Derived from the owner's own fields, so it stays consistent with them.
371	     */
372	    @Transient
373	    public String getIdentityKey() {
374	        String telephonePart = this.telephone == null ? "" : this.telephone;
375	        String emailPart = this.email == null ? "" : this.email;
376	        String householdPart = this.householdId == null ? "" : this.householdId;
377	        return telephonePart + "|" + emailPart + "|" + householdPart;
378	    }
379	
380	    /**
381	     * The owner's age band relative to their registration date: {@code "MINOR"} when
382	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
383	     * Derived from the owner's own birth and registration dates, so it stays consistent
384	     * with them; null until a birth date is on file. See {@link AgeBand}.
385	     */
386	    @Transient
387	    public String getAgeBand() {
388	        if (this.birthDate == null || this.registrationDate == null) {
389	            return null;
390	        }
391	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
392	    }
393	
394	    /**
395	     * Normalize the registration date before persisting: default it to the server's
396	     * current date when none was supplied, then roll it forward onto a business day so
397	     * every newly persisted owner is registered on a weekday.
398	     */
399	    @PrePersist
400	    void normalizeRegistrationDate() {
401	        if (this.registrationDate == null) {
402	            this.registrationDate = LocalDate.now();
403	        }
404	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
405	    }
406	
407	    protected Set<Pet> getPetsInternal() {
408	        if (this.pets == null) {
409	            this.pets = new HashSet<>();
410	        }
411	        return this.pets;
412	    }
413	
414	    protected void setPetsInternal(Set<Pet> pets) {
415	        this.pets = pets;
416	    }
417	
418	    public List<Pet> getPets() {
419	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
420	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
421	        return Collections.unmodifiableList(sortedPets);
422	    }
423	
424	    public void setPets(List<Pet> pets) {
425	        this.pets = new HashSet<>(pets);
426	    }
427	
428	    public void addPet(Pet pet) {
429	        getPetsInternal().add(pet);
430	        pet.setOwner(this);
431	    }
432	
433	    /**
434	     * Return the Pet with the given name, or null if none found for this Owner.
435	     *
436	     * @param name to test
437	     * @return true if pet name is already in use
438	     */
439	    public Pet getPet(String name) {
440	        return getPet(name, false);
441	    }
442	
443	    /**
444	     * Return the Pet with the given name, or null if none found for this Owner.
445	     *
446	     * @param name to test
447	     * @return true if pet name is already in use
448	     */
449	    public Pet getPet(String name, boolean ignoreNew) {
450	        name = name.toLowerCase();
451	        for (Pet pet : getPetsInternal()) {
452	            if (!ignoreNew || !pet.isNew()) {
453	                String compName = pet.getName();
454	                compName = compName.toLowerCase();
455	                if (compName.equals(name)) {
456	                    return pet;
457	                }
458	            }
459	        }
460	        return null;
461	    }
462	
463	    public Pet getPet(Integer petId) {
464	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
465	    }
466	
467	    @Override
468	    public String toString() {
469	        return new ToStringCreator(this)
470	
471	            .append("id", this.getId())
472	            .append("new", this.isNew())
473	            .append("lastName", this.getLastName())
474	            .append("firstName", this.getFirstName())
475	            .append("address", this.address)
476	            .append("city", this.city)
477	            .append("telephone", this.telephone)
478	            .toString();
479	    }
480	}
